from pathlib import Path

ROOT = Path('.')

def replace(path, old, new):
    p = ROOT / path
    text = p.read_text()
    if old not in text:
        raise RuntimeError(f'pattern not found: {path}')
    p.write_text(text.replace(old, new, 1))

replace('src/ai/checkpoint.js', 'export async function loadCheckpoint(path, { Model, Tokenizer }) {', 'export async function loadCheckpoint(path, { Model, Tokenizer, requireProductionReady = false }) {')
replace('src/ai/checkpoint.js', '  if (data.version !== 1) throw new Error(`Unsupported checkpoint version: ${data.version}`);', "  if (data.version !== 1) throw new Error(`Unsupported checkpoint version: ${data.version}`);\n  if (requireProductionReady && data.metadata?.production_ready !== true) throw new Error('Checkpoint is not marked production_ready.');")

replace('src/core/knowledge.js', "async search(query, { limit = 8 } = {}) {\n    const safeLimit = Math.min(Math.max(Number(limit) || 8, 1), 20);\n    return this.request('/rest/v1/rpc/search_astracore_knowledge', { method:'POST', headers:{Prefer:'return=representation'}, body:JSON.stringify({search_query:String(query).slice(0,2000),query_embedding:null,result_limit:safeLimit}) });\n  }", "async search(query, { limit = 8, queryEmbedding = null } = {}) {\n    const safeLimit = Math.min(Math.max(Number(limit) || 8, 1), 20);\n    const embedding = Array.isArray(queryEmbedding) && queryEmbedding.length === 384 ? queryEmbedding : null;\n    return this.request('/rest/v1/rpc/search_astracore_knowledge', { method:'POST', headers:{Prefer:'return=representation'}, body:JSON.stringify({search_query:String(query).slice(0,2000),query_embedding:embedding,result_limit:safeLimit}) });\n  }")

